const mediterSeasons: Array<{ key: string; season: "spring" | "summer" | "autumn" | "winter"; year: number }> = [
  { key: "spring-2026", season: "spring", year: 2026 },
  { key: "summer-2025", season: "summer", year: 2025 },
  { key: "autumn-2025", season: "autumn", year: 2025 },
  { key: "winter-2026", season: "winter", year: 2026 },
];

for (const s of mediterSeasons) {
  const story = seasonalStories({
    household: { entries: mediterHistory },
    season: { season: s.season, year: s.year },
    now: NOW,
  });
  console.log(formatSeasonalStory(story));
  checkTrust(`mediterranean ${s.key}`, story);
  report[`mediterranean-${s.key}`] = story;
  console.log();
}

// Targeted assertions on specific seasons
const medSummer = seasonalStories({
  household: { entries: mediterHistory },
  season: { season: "summer", year: 2025 },
  now: NOW,
});
expect("med summer: season summary present", blockTypes(medSummer).includes("season_summary"));
expect("med summer: seasonal habits present", blockTypes(medSummer).includes("seasonal_habits"));
expect(
  "med summer: looking ahead points to autumn foods",
  medSummer.blocks
    .find((b) => b.type === "looking_ahead")
    ?.cards.some((c) => c.headline.toLowerCase().includes("autumn")) ?? false,
);

const medSpring = seasonalStories({
  household: { entries: mediterHistory },
  season: { season: "spring", year: 2026 },
  now: NOW,
});
expect(
  "med spring: fennel/asparagus surfaced as discoveries",
  medSpring.blocks
    .find((b) => b.type === "discoveries")
    ?.cards.some((c) =>
      /fennel|asparagus/i.test(c.headline + JSON.stringify(c.facts)),
    ) ?? false,
);

const medAutumn = seasonalStories({
  household: { entries: mediterHistory },
  season: { season: "autumn", year: 2025 },
  now: NOW,
});
expect("med autumn: season summary present", blockTypes(medAutumn).includes("season_summary"));

