// ════════════════════════════════════════════════════════════════════════════
// 5. SILENCE CONTRACT — a barely-cooked season stays silent
// ════════════════════════════════════════════════════════════════════════════

console.log(line);
console.log("5. SILENCE CONTRACT — sparse season stays silent\n");

const sparseStory = seasonalStories({
  household: {
    entries: [
      { food: "tomato", foodName: "Tomato", date: d("2026-04-02"), source: "planned" },
      { food: "carrot", foodName: "Carrot", date: d("2026-05-10"), source: "planned" },
    ],
  },
  season: { season: "spring", year: 2026 },
  now: NOW,
});
console.log(formatSeasonalStory(sparseStory));
expect(
  "sparse season: no season summary (below 3-meal threshold)",
  !blockTypes(sparseStory).includes("season_summary"),
);
expect(
  "sparse season: no favourite moments, no habits",
  !blockTypes(sparseStory).includes("favourite_moments") &&
    !blockTypes(sparseStory).includes("seasonal_habits"),
);

const emptyStory = seasonalStories({
  household: { entries: [] },
  season: { season: "spring", year: 2026 },
  now: NOW,
});
expect("empty season: looking-ahead may still appear, no memory blocks",
  emptyStory.blocks.every((b) => b.type === "looking_ahead"));
console.log();

// ════════════════════════════════════════════════════════════════════════════
// 6. BLOCK NARROWING + DEFAULT SEASON
// ════════════════════════════════════════════════════════════════════════════

console.log(line);
console.log("6. BLOCK NARROWING + default season from now\n");

const narrowed = seasonalStories({
  household: { entries: mediterHistory },
  season: { season: "summer", year: 2025 },
  now: NOW,
  blocks: ["season_summary"],
});
expect(
  "block narrowing: only season_summary returned",
  narrowed.blocks.length > 0 && narrowed.blocks.every((b) => b.type === "season_summary"),
);

const defaulted = seasonalStories({
  household: { entries: mediterHistory },
  now: NOW, // 2026-06-22 → summer 2026
});
expect(
  "default season: derived from now (summer 2026)",
  defaulted.season === "summer" && defaulted.year === 2026,
);
console.log();

// ════════════════════════════════════════════════════════════════════════════
// 7. TRUST GATE — all authored text across all examples
// ════════════════════════════════════════════════════════════════════════════

console.log(line);
console.log("7. TRUST GATE — all seasonal text across all examples\n");

const allStories: SeasonalStory[] = [
  medSummer, medSpring, medAutumn,
  familyStory, vegStory, legumeStory,
];
let totalCards = 0;
let trustFailures = 0;
for (const s of allStories) {
  totalCards += allCards(s).length;
  try {
    assertTrustworthy(allCards(s));
  } catch (e) {
    trustFailures++;
    failures++;
    console.log(`  ✗ Trust violation: ${(e as Error).message}`);
  }
}
expect(
  `all ${totalCards} seasonal cards across all examples pass the trust gate`,
  trustFailures === 0,
);
console.log();

// ── Persist report ──────────────────────────────────────────────────────────

const outDir = join(process.cwd(), "data", "seasonal");
mkdirSync(outDir, { recursive: true });
const outPath = join(outDir, "ws11-seasonal-stories-report.json");
writeFileSync(
  outPath,
  JSON.stringify(
    {
      workstream: "WS11 — Seasonal Stories Engine",
      generatedAt: new Date().toISOString(),
      totalCards,
      examples: report,
    },
    null,
    2,
  ),
);
console.log(`Report written: ${outPath}`);

// ── Summary ───────────────────────────────────────────────────────────────────

console.log(`\n${line}`);
if (failures === 0) {
  console.log("✓ WS11 — all worked examples, gates and trust checks passed.");
} else {
  console.log(`✗ WS11 — ${failures} check(s) failed.`);
  process.exit(1);
}
